import{_ as t,a0 as o,w as d,s as r,ao as l,I as p,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击 | LCTT x X-CMD","titleTemplate":false,"description":"用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171127 Protecting Your Website From Application Layer DOS Attacks With mod","title":"用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击","tag":"201802","desc":""},"relativePath":"201802/20171127 Protecting Your Website From Application Layer DOS Attacks With mod.md","filePath":"[post].md"}'),h={name:"201802/20171127 Protecting Your Website From Application Layer DOS Attacks With mod.md"};function c(g,s,u,b,k,v){const e=o("Link");return d(),r("div",null,[s[23]||(s[23]=l('<h1 id="用-apache-服务器模块保护您的网站免受应用层-dos-攻击" tabindex="-1">用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击 <a class="header-anchor" href="#用-apache-服务器模块保护您的网站免受应用层-dos-攻击" aria-label="Permalink to “用 Apache 服务器模块保护您的网站免受应用层 DOS 攻击”">​</a></h1><p>有多种可以导致网站下线的攻击方法，比较复杂的方法要涉及数据库和编程方面的技术知识。一个更简单的方法被称为“<ruby>拒绝服务<rt>Denial Of Service</rt></ruby>”（DOS）攻击。这个攻击方法的名字来源于它的意图：使普通客户或网站访问者的正常服务请求被拒绝。</p><p>一般来说，有两种形式的 DOS 攻击：</p><ol><li>OSI 模型的三、四层，即网络层攻击</li><li>OSI 模型的七层，即应用层攻击</li></ol><p>第一种类型的 DOS 攻击——网络层，发生于当大量的垃圾流量流向网页服务器时。当垃圾流量超过网络的处理能力时，网站就会宕机。</p><p>第二种类型的 DOS 攻击是在应用层，是利用合法的服务请求，而不是垃圾流量。当页面请求数量超过网页服务器能承受的容量时，即使是合法访问者也将无法使用该网站。</p><p>本文将着眼于缓解应用层攻击，因为减轻网络层攻击需要大量的可用带宽和上游提供商的合作，这通常不是通过配置网络服务器就可以做到的。</p>',7)),p("p",null,[s[2]||(s[2]=a("通过配置普通的网页服务器，可以保护网页免受应用层攻击，至少是适度的防护。防止这种形式的攻击是非常重要的，因为 ",-1)),i(e,{href:"https://www.cloudflare.com"},{default:n(()=>[...s[0]||(s[0]=[a("Cloudflare",-1)])]),_:1}),s[3]||(s[3]=a(" 最近 ",-1)),i(e,{href:"https://blog.cloudflare.com/the-new-ddos-landscape/"},{default:n(()=>[...s[1]||(s[1]=[a("报告称",-1)])]),_:1}),s[4]||(s[4]=a(" 网络层攻击的数量正在减少，而应用层攻击的数量则在增加。",-1))]),p("p",null,[s[7]||(s[7]=a("本文将介绍如何使用 ",-1)),i(e,{href:"https://www.zdziarski.com/blog/"},{default:n(()=>[...s[5]||(s[5]=[a("zdziarski",-1)])]),_:1}),s[8]||(s[8]=a(" 开发的 Apache2 的模块 ",-1)),i(e,{href:"https://github.com/jzdziarski/mod_evasive"},{default:n(()=>[...s[6]||(s[6]=[a("mod_evasive",-1)])]),_:1}),s[9]||(s[9]=a("。",-1))]),s[24]||(s[24]=l(`<p>另外，mod_evasive 会阻止攻击者通过尝试数百个用户名和密码的组合来进行猜测（即暴力攻击）的企图。</p><p>mod_evasive 会记录来自每个 IP 地址的请求的数量。当这个数字超过相应 IP 地址的几个阈值之一时，会出现一个错误页面。错误页面所需的资源要比一个能够响应合法访问的在线网站少得多。</p><h3 id="在-ubuntu-16-04-上安装-mod-evasive" tabindex="-1">在 Ubuntu 16.04 上安装 mod_evasive <a class="header-anchor" href="#在-ubuntu-16-04-上安装-mod-evasive" aria-label="Permalink to “在 Ubuntu 16.04 上安装 mod_evasive”">​</a></h3><p>Ubuntu 16.04 默认的软件库中包含了 mod_evasive，名称为 “libapache2-mod-evasive”。您可以使用 <code>apt-get</code> 来完成安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update</span></span>
<span class="line"><span>apt-get upgrade</span></span>
<span class="line"><span>apt-get install libapache2-mod-evasive</span></span></code></pre></div><p>现在我们需要配置 mod_evasive。</p><p>它的配置文件位于 <code>/etc/apache2/mods-available/evasive.conf</code>。默认情况下，所有模块的设置在安装后都会被注释掉。因此，在修改配置文件之前，模块不会干扰到网站流量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_evasive20.c&gt;</span></span>
<span class="line"><span>   #DOSHashTableSize    3097</span></span>
<span class="line"><span>   #DOSPageCount        2</span></span>
<span class="line"><span>   #DOSSiteCount        50</span></span>
<span class="line"><span>   #DOSPageInterval     1</span></span>
<span class="line"><span>   #DOSSiteInterval     1</span></span>
<span class="line"><span>   #DOSBlockingPeriod   10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   #DOSEmailNotify      you@yourdomain.com</span></span>
<span class="line"><span>   #DOSSystemCommand    &quot;su - someuser -c &#39;/sbin/... %s ...&#39;&quot;</span></span>
<span class="line"><span>   #DOSLogDir           &quot;/var/log/mod_evasive&quot;</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><p>第一部分的参数的含义如下：</p><ul><li><code>DOSHashTableSize</code> - 正在访问网站的 IP 地址列表及其请求数的当前列表。</li><li><code>DOSPageCount</code> - 在一定的时间间隔内，每个页面的请求次数。时间间隔由 DOSPageInterval 定义。</li><li><code>DOSPageInterval</code> - mod_evasive 统计页面请求次数的时间间隔。</li><li><code>DOSSiteCount</code> - 与 <code>DOSPageCount</code> 相同，但统计的是来自相同 IP 地址对网站内任何页面的请求数量。</li><li><code>DOSSiteInterval</code> - mod_evasive 统计网站请求次数的时间间隔。</li><li><code>DOSBlockingPeriod</code> - 某个 IP 地址被加入黑名单的时长（以秒为单位）。</li></ul><p>如果使用上面显示的默认配置，则在如下情况下，一个 IP 地址会被加入黑名单：</p><ul><li>每秒请求同一页面超过两次。</li><li>每秒请求 50 个以上不同页面。</li></ul><p>如果某个 IP 地址超过了这些阈值，则被加入黑名单 10 秒钟。</p><p>这看起来可能不算久，但是，mod_evasive 将一直监视页面请求，包括在黑名单中的 IP 地址，并重置其加入黑名单的起始时间。只要一个 IP 地址一直尝试使用 DOS 攻击该网站，它将始终在黑名单中。</p><p>其余的参数是：</p><ul><li><code>DOSEmailNotify</code> - 用于接收 DOS 攻击信息和 IP 地址黑名单的电子邮件地址。</li><li><code>DOSSystemCommand</code> - 检测到 DOS 攻击时运行的命令。</li><li><code>DOSLogDir</code> - 用于存放 mod_evasive 的临时文件的目录。</li></ul><h3 id="配置-mod-evasive" tabindex="-1">配置 mod_evasive <a class="header-anchor" href="#配置-mod-evasive" aria-label="Permalink to “配置 mod_evasive”">​</a></h3><p>默认的配置是一个很好的开始，因为它不会阻塞任何合法的用户。取消配置文件中的所有参数（<code>DOSSystemCommand</code> 除外）的注释，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;IfModule mod_evasive20.c&gt;</span></span>
<span class="line"><span>   DOSHashTableSize   3097</span></span>
<span class="line"><span>   DOSPageCount       2</span></span>
<span class="line"><span>   DOSSiteCount       50</span></span>
<span class="line"><span>   DOSPageInterval    1</span></span>
<span class="line"><span>   DOSSiteInterval    1</span></span>
<span class="line"><span>   DOSBlockingPeriod  10</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   DOSEmailNotify       JohnW@example.com</span></span>
<span class="line"><span>   #DOSSystemCommand    &quot;su - someuser -c &#39;/sbin/... %s ...&#39;&quot;</span></span>
<span class="line"><span>   DOSLogDir            &quot;/var/log/mod_evasive&quot;</span></span>
<span class="line"><span>&lt;/IfModule&gt;</span></span></code></pre></div><p>必须要创建日志目录并且要赋予其与 apache 进程相同的所有者。这里创建的目录是 <code>/var/log/mod_evasive</code> ，并且在 Ubuntu 上将该目录的所有者和组设置为 <code>www-data</code> ，与 Apache 服务器相同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir /var/log/mod_evasive</span></span>
<span class="line"><span>chown www-data:www-data /var/log/mod_evasive</span></span></code></pre></div><p>在编辑了 Apache 的配置之后，特别是在正在运行的网站上，在重新启动或重新加载之前，最好检查一下语法，因为语法错误将影响 Apache 的启动从而使网站宕机。</p><p>Apache 包含一个辅助命令，是一个配置语法检查器。只需运行以下命令来检查您的语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apachectl configtest</span></span></code></pre></div><p>如果您的配置是正确的，会得到如下结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Syntax OK</span></span></code></pre></div><p>但是，如果出现问题，您会被告知在哪部分发生了什么错误，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AH00526: Syntax error on line 6 of /etc/apache2/mods-enabled/evasive.conf:</span></span>
<span class="line"><span>DOSSiteInterval takes one argument, Set site interval</span></span>
<span class="line"><span>Action &#39;configtest&#39; failed.</span></span>
<span class="line"><span>The Apache error log may have more information.</span></span></code></pre></div><p>如果您的配置通过了 configtest 的测试，那么这个模块可以安全地被启用并且 Apache 可以重新加载：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a2enmod evasive</span></span>
<span class="line"><span>systemctl reload apache2.service</span></span></code></pre></div><p>mod_evasive 现在已配置好并正在运行了。</p><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to “测试”">​</a></h3><p>为了测试 mod_evasive，我们只需要向服务器提出足够的网页访问请求，以使其超出阈值，并记录来自 Apache 的响应代码。</p><p>一个正常并成功的页面请求将收到如下响应：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK</span></span></code></pre></div><p>但是，被 mod_evasive 拒绝的将返回以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 403 Forbidden</span></span></code></pre></div><p>以下脚本会尽可能迅速地向本地主机（127.0.0.1，localhost）的 80 端口发送 HTTP 请求，并打印出每个请求的响应代码。</p><p>你所要做的就是把下面的 bash 脚本复制到一个文件中，例如 <code>mod_evasive_test.sh</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for i in {1..50}; do</span></span>
<span class="line"><span>        curl -s -I 127.0.0.1 | head -n 1</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>这个脚本的部分含义如下：</p><ul><li><code>curl</code> - 这是一个发出网络请求的命令。 <ul><li><code>-s</code> - 隐藏进度表。</li><li><code>-I</code> - 仅显示响应头部信息。</li></ul></li><li><code>head</code> - 打印文件的第一部分。 <ul><li><code>-n 1</code> - 只显示第一行。</li></ul></li></ul><p>然后赋予其执行权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod 755 mod_evasive_test.sh</span></span></code></pre></div><p>在启用 mod_evasive <strong>之前</strong>，脚本运行时，将会看到 50 行 “HTTP / 1.1 200 OK” 的返回值。</p><p>但是，启用 mod_evasive 后，您将看到以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>HTTP/1.1 403 Forbidden</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>前两个请求被允许，但是在同一秒内第三个请求发出时，mod_evasive 拒绝了任何进一步的请求。您还将收到一封电子邮件（邮件地址在选项 <code>DOSEmailNotify</code> 中设置），通知您有 DOS 攻击被检测到。</p><p>mod_evasive 现在已经在保护您的网站啦！</p><hr>`,50)),p("p",null,[s[11]||(s[11]=a("via: ",-1)),i(e,{href:"https://bash-prompt.net/guides/mod_proxy/"},{default:n(()=>[...s[10]||(s[10]=[a("https://bash-prompt.net/guides/mod_proxy/",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("作者：",-1)),i(e,{href:"https://bash-prompt.net/about/"},{default:n(()=>[...s[12]||(s[12]=[a("Elliot Cooper",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),i(e,{href:"https://github.com/jessie-pang"},{default:n(()=>[...s[13]||(s[13]=[a("jessie-pang",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const y=t(h,[["render",c]]);export{S as __pageData,y as default};
